configuration.decoder:
var data = typeof payload === 'string' ? JSON.parse(payload) : JSON.parse(String.fromCharCode.apply(null, payload));
var deviceName = metadata.topic.split('/')[0];

if (deviceName.indexOf('shellyhtg3-') !== 0) {
    return null;
}

var result = {
    deviceName: deviceName,
    deviceType: 'Shelly H&T G3',
    telemetry: {}
};

var topic = metadata.topic;

if (topic.indexOf('/status/temperature:0') !== -1) {
    result.telemetry = { temperatura: data.tC };
} else if (topic.indexOf('/status/humidity:0') !== -1) {
    result.telemetry = { humedad: data.rh };
} else if (topic.indexOf('/status/devicepower:0') !== -1) {
    result.telemetry = {
        bateria_voltaje: data.battery ? data.battery.V : null,
        bateria_porcentaje: data.battery ? data.battery.percent : null
    };
}

return result;

